-- Chaotic Gaming Core: foundational identity, access control and operations.
-- IDs are generated by the application (UUIDv7 recommended).
-- Apply with the migration runner in a transaction.

CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS operations;

CREATE TABLE core.principals (
  id UUID PRIMARY KEY,
  principal_type TEXT NOT NULL CHECK (principal_type IN ('user', 'service')),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'suspended', 'disabled', 'deletion_pending', 'deleted')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE core.users (
  principal_id UUID PRIMARY KEY REFERENCES core.principals(id) ON DELETE RESTRICT,
  username TEXT NOT NULL,
  email TEXT,
  email_verified_at TIMESTAMPTZ,
  password_hash TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT users_username_nonempty CHECK (length(trim(username)) BETWEEN 3 AND 32),
  CONSTRAINT users_email_normalized CHECK (email IS NULL OR email = lower(trim(email)))
);
CREATE UNIQUE INDEX users_username_lower_uq ON core.users (lower(username));
CREATE UNIQUE INDEX users_email_lower_uq ON core.users (lower(email)) WHERE email IS NOT NULL;

CREATE TABLE core.user_profiles (
  principal_id UUID PRIMARY KEY REFERENCES core.users(principal_id) ON DELETE CASCADE,
  display_name TEXT,
  avatar_url TEXT,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  locale TEXT NOT NULL DEFAULT 'en-US',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE core.linked_accounts (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.users(principal_id) ON DELETE RESTRICT,
  provider TEXT NOT NULL,
  external_id TEXT NOT NULL,
  external_username TEXT,
  verified_at TIMESTAMPTZ,
  linked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  unlinked_at TIMESTAMPTZ,
  CONSTRAINT linked_accounts_provider_nonempty CHECK (length(trim(provider)) > 0),
  CONSTRAINT linked_accounts_external_id_nonempty CHECK (length(trim(external_id)) > 0)
);
CREATE UNIQUE INDEX linked_accounts_active_provider_identity_uq
  ON core.linked_accounts (provider, external_id) WHERE unlinked_at IS NULL;
CREATE INDEX linked_accounts_principal_idx ON core.linked_accounts (principal_id);

CREATE TABLE core.identity_verifications (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.users(principal_id) ON DELETE CASCADE,
  provider TEXT NOT NULL,
  external_id TEXT NOT NULL,
  verification_method TEXT NOT NULL,
  challenge_hash TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  verified_at TIMESTAMPTZ,
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX identity_verifications_pending_idx
  ON core.identity_verifications (expires_at) WHERE verified_at IS NULL;

CREATE TABLE core.auth_sessions (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.principals(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at TIMESTAMPTZ,
  user_agent TEXT,
  ip_address INET
);
CREATE INDEX auth_sessions_active_principal_idx
  ON core.auth_sessions (principal_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE core.roles (
  id UUID PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  description TEXT
);
CREATE TABLE core.permissions (
  id UUID PRIMARY KEY,
  permission_key TEXT NOT NULL UNIQUE,
  description TEXT
);
CREATE TABLE core.role_permissions (
  role_id UUID NOT NULL REFERENCES core.roles(id) ON DELETE CASCADE,
  permission_id UUID NOT NULL REFERENCES core.permissions(id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_id)
);
CREATE TABLE core.principal_role_assignments (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.principals(id) ON DELETE CASCADE,
  role_id UUID NOT NULL REFERENCES core.roles(id) ON DELETE RESTRICT,
  scope_type TEXT NOT NULL CHECK (scope_type IN ('platform', 'game', 'cluster', 'server', 'guild')),
  scope_id TEXT,
  granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  granted_by UUID REFERENCES core.principals(id) ON DELETE SET NULL,
  CONSTRAINT role_assignment_scope_shape CHECK (
    (scope_type = 'platform' AND scope_id IS NULL) OR
    (scope_type <> 'platform' AND scope_id IS NOT NULL AND length(trim(scope_id)) > 0)
  ),
  CONSTRAINT role_assignment_expiry CHECK (expires_at IS NULL OR expires_at > granted_at)
);
CREATE INDEX principal_role_assignments_lookup_idx
  ON core.principal_role_assignments (principal_id, scope_type, scope_id);

CREATE TABLE core.service_accounts (
  principal_id UUID PRIMARY KEY REFERENCES core.principals(id) ON DELETE RESTRICT,
  application_name TEXT NOT NULL,
  description TEXT,
  credential_rotated_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE core.service_credentials (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.service_accounts(principal_id) ON DELETE CASCADE,
  secret_hash TEXT NOT NULL UNIQUE,
  scopes TEXT[] NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  last_used_at TIMESTAMPTZ
);
CREATE INDEX service_credentials_active_idx
  ON core.service_credentials (principal_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE operations.audit_logs (
  id UUID PRIMARY KEY,
  actor_principal_id UUID REFERENCES core.principals(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  resource_type TEXT,
  resource_id TEXT,
  outcome TEXT NOT NULL CHECK (outcome IN ('success', 'failure', 'denied')),
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_actor_created_idx
  ON operations.audit_logs (actor_principal_id, created_at DESC);
CREATE INDEX audit_logs_resource_idx
  ON operations.audit_logs (resource_type, resource_id, created_at DESC);

CREATE TABLE operations.event_outbox (
  id UUID PRIMARY KEY,
  event_type TEXT NOT NULL,
  aggregate_type TEXT NOT NULL,
  aggregate_id TEXT NOT NULL,
  payload JSONB NOT NULL,
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  available_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at TIMESTAMPTZ,
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  last_error TEXT
);
CREATE INDEX event_outbox_pending_idx
  ON operations.event_outbox (available_at, occurred_at)
  WHERE published_at IS NULL;

CREATE TABLE operations.idempotency_keys (
  id UUID PRIMARY KEY,
  principal_id UUID NOT NULL REFERENCES core.principals(id) ON DELETE CASCADE,
  idempotency_key TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  response_status INTEGER,
  response_body JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  UNIQUE (principal_id, idempotency_key)
);
CREATE INDEX idempotency_keys_expiry_idx ON operations.idempotency_keys (expires_at);
